def summarize(rows):
    """Aggregate revenue by region.

    Args:
        rows: list of dicts with keys 'region' (str) and 'revenue' (numeric or numeric string).

    Returns:
        dict mapping region -> total revenue as a float. Rows with a missing or
        unparseable revenue are silently ignored.
    """
    totals = {}
    for row in rows:
        region = row.get("region")
        if region is None:
            continue
        raw = row.get("revenue")
        if raw is None:
            continue
        try:
            revenue = float(raw)
        except (TypeError, ValueError):
            continue
        totals[region] = totals.get(region, 0.0) + revenue
    return totals

from summarize import summarize


def test_basic():
    rows = [
        {"region": "EU", "revenue": 100},
        {"region": "EU", "revenue": 50},
        {"region": "NA", "revenue": 200},
    ]
    assert summarize(rows) == {"EU": 150.0, "NA": 200.0}


def test_numeric_strings():
    rows = [
        {"region": "EU", "revenue": "10.5"},
        {"region": "EU", "revenue": "3.5"},
    ]
    assert summarize(rows) == {"EU": 14.0}


def test_missing_revenue_ignored():
    rows = [
        {"region": "EU", "revenue": None},
        {"region": "EU", "revenue": 10},
    ]
    assert summarize(rows) == {"EU": 10.0}


def test_missing_region_ignored():
    rows = [
        {"revenue": 10},
        {"region": "EU", "revenue": 5},
    ]
    assert summarize(rows) == {"EU": 5.0}


def test_unparseable_revenue_ignored():
    rows = [
        {"region": "EU", "revenue": "foo"},
        {"region": "EU", "revenue": 7},
    ]
    assert summarize(rows) == {"EU": 7.0}


def test_empty_input():
    assert summarize([]) == {}


def test_all_invalid():
    rows = [
        {"region": "EU", "revenue": None},
        {"region": "EU", "revenue": "bad"},
    ]
    assert summarize(rows) == {}


def test_return_type_is_float():
    rows = [{"region": "EU", "revenue": 1}]
    result = summarize(rows)
    assert isinstance(result["EU"], float)

